     1	#!/bin/bash
     2	# book.sh ROOM DATE START END WHO: add a booking unless the room is taken at that time.
     3	set -u
     4	. "$(dirname "$0")/lib/slots.sh"
     5	BOOKINGS=${BOOKINGS:-data/bookings.tsv}
     6	room=$1 date=$2 start=$3 end=$4 who=$5
     7	s=$(to_min "$start"); e=$(to_min "$end")
     8	[ "$s" -lt "$e" ] || { echo "end must be after start" >&2; exit 2; }
     9	while IFS=$'\t' read -r r d bs be bw; do
    10	  case "$r" in '#'*|'') continue ;; esac
    11	  [ "$r" = "$room" ] && [ "$d" = "$date" ] || continue
    12	  if overlaps "$s" "$e" "$(to_min "$bs")" "$(to_min "$be")"; then echo "conflict: $r $d $bs-$be $bw" >&2; exit 1; fi
    13	done < "$BOOKINGS"
    14	printf '%s\t%s\t%s\t%s\t%s\n' "$room" "$date" "$start" "$end" "$who" >> "$BOOKINGS"
    15	echo "booked: $room $date $start-$end $who"
